 body={"base_row_count":40,"expected_fanout_multiplier":2.63,"expected_trap_05_anomaly_count":1,"generated_files":["crm_customers.parquet","sales_orders.parquet","order_items.parquet","order_payments.parquet","billing_subscriptions.parquet","marketing_leads.parquet","payment_events_wave1.parquet","payment_events_wave3.parquet"],"naive_fanout_inflated_revenue_usd":93766.0,"planted_traps":[{"category":"homonym_chasm","description":"Both tables use sequential integer surrogate account_id (1..N) for unrelated entity domains (Billing Tax Accounts vs Ad Marketing Leads).","expected_action":"require_steward_verification_then_forbidden_join","left_dataset":"billing_subscriptions","left_field":"account_id","right_dataset":"marketing_leads","right_field":"account_id","trap_id":"TRAP-01"},{"category":"cryptic_synonym_fk","description":"Zero column-name similarity, but >98% value inclusion ratio and clean N:1 cardinality.","expected_action":"sync_joinable_with","left_dataset":"sales_orders","left_field":"cust_ref_key","right_dataset":"crm_customers","right_field":"party_uuid","trap_id":"TRAP-02"},{"category":"nm_fanout_inflation","description":"Joining multi-row order_items to multi-row order_payments on order_id inflates payment revenue by ~2.5x.","expected_action":"pre_aggregate_before_join","left_dataset":"order_items","left_field":"order_id","right_dataset":"order_payments","right_field":"order_id","trap_id":"TRAP-03"},{"category":"temporal_schema_and_unit_drift","description":"Wave 3 renames user_id -> client_id and shifts amount from USD (~120.0) to integer cents (~12000.0, 100x scale shift).","expected_action":"mark_drifted_and_require_unit_conversion","left_dataset":"payment_events_wave1","left_field":"amount","right_dataset":"payment_events_wave3","right_field":"amount","trap_id":"TRAP-04"},{"category":"non_sql_algorithmic_anomaly","description":"Detect outlier orders (z_score > 3.0) and composite churn risk via sandboxed Python algorithm.","expected_action":"execute_sandboxed_python_algorithm_and_promote_aad_skill","left_dataset":"sales_orders","left_field":"order_total_usd","right_dataset":"sales_orders","right_field":"status","trap_id":"TRAP-05"}],"seed":42,"stat_traps":[],"true_total_order_revenue_usd":35710.5,"wave1_payment_mean_usd":119.5,"wave3_payment_mean_cents":11950.0}

