 body={"id":1,"jsonrpc":"2.0","result":{"tools":[{"description":"List all hydrated, SHA-256-pinned built-in statistical algorithms.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object"},"name":"algorithm_browse"},{"description":"Health-check MCP tool returning a greeting from data-engine.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"name":{"description":"Optional name of the caller or entity to greet (defaults to 'world').","type":["string","null"]}},"type":"object"},"name":"hello"},{"description":"Compute Pearson/Spearman/Kendall correlation matrices with FDR adjustment, partial correlations, and VIF multicollinearity diagnostics.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"columns":{"description":"Numeric column names to include in correlation and VIF analysis.","items":{"type":"string"},"type":"array"},"control_cols":{"description":"Optional control columns for partial correlation computation.","items":{"type":"string"},"type":["array","null"]},"correction":{"description":"Multiple-testing correction method (default 'fdr_bh').","type":["string","null"]},"input_binding":{"description":"Dataset input binding object containing dataset_name and parquet_path."},"methods":{"description":"Correlation methods to compute (e.g. ['pearson', 'spearman', 'kendall']).","items":{"type":"string"},"type":["array","null"]},"sampling":{"description":"Optional seeded sampling specification object."}},"required":["input_binding","columns"],"type":"object"},"name":"stat_correlation_vif"},{"description":"Compute distributional moments, quantiles, Shapiro-Wilk/D'Agostino normality, outlier counts, and learned field traits.","inputSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","properties":{"columns":{"description":"List of numeric column names to describe and diagnose.","items":{"type":"string"},"type":"array"},"input_binding":{"description":"Data